<div class="admin-welcome"><div><h2>A fresh look at your store.</h2><p>Your orders, your customers, your next little milestone.</p></div><a href="<?= e(url('admin/edit',['module'=>'products'])) ?>" class="btn btn-primary">+ Add a product</a></div><form class="report-filter" method="get"><input type="hidden" name="r" value="admin"><label>From<input class="form-control" type="date" name="from" value="<?= e($from) ?>"></label><label>To<input class="form-control" type="date" name="to" value="<?= e($to) ?>"></label><button class="btn btn-outline-primary">Apply range</button><a class="text-link" href="<?= e(url('admin/export',['module'=>'sales','from'=>$from,'to'=>$to])) ?>">Export sales ↓</a></form><div class="metric-grid"><?php foreach([['Verified sales',money($metrics['sales']),'Selected date range'],['Today’s sales',money($metrics['today']),'Verified collections today'],['Orders',$metrics['orders'],'Selected date range'],['Customers',$metrics['customers'],'Registered accounts'],['Active products',$metrics['products'],'In your pantry'],['Low stock',$metrics['low'],'Variants needing attention']] as $metric): ?><div class="metric-card"><span><?= e($metric[0]) ?></span><strong><?= e($metric[1]) ?></strong><small><?= e($metric[2]) ?></small></div><?php endforeach ?></div><div class="chart-grid"><?php foreach(['daily'=>'Daily revenue','monthly'=>'Monthly revenue','statuses'=>'Order status','best'=>'Best-selling products','category'=>'Category sales (before discounts)'] as $key=>$label): ?><section class="panel chart-panel"><h3><?= e($label) ?></h3><?php $rows=$metrics[$key];$max=$rows?max(array_column($rows,'value')):1;if(!$rows): ?><div class="chart-empty"><span>◴</span><p>No data for this period.<br>Your real store activity will appear here.</p></div><?php else: ?><div class="bar-chart"><?php foreach($rows as $bar): ?><div class="chart-row"><span><?= e($bar['label']) ?></span><div><i style="width:<?= round($bar['value']/max(1,$max)*100) ?>%"></i></div><strong><?= in_array($key,['daily','monthly','category'])?money($bar['value']):$bar['value'] ?></strong></div><?php endforeach ?></div><?php endif ?></section><?php endforeach ?></div><section class="panel mt-4"><div class="section-heading"><h3>Latest orders</h3><a class="text-link" href="<?= e(url('admin/orders')) ?>">View all →</a></div><?php $orders=$recent;require ROOT.'/app/Views/admin/order-table.php'; ?></section><details class="panel mt-4"><summary>Change your admin password</summary><form action="<?= e(url('admin/password')) ?>" method="post" class="form-grid mt-3"><?= csrf() ?><label>Current password<input class="form-control" type="password" name="current_password" required></label><label>New password<input class="form-control" type="password" name="new_password" minlength="10" required></label><button class="btn btn-primary">Update password</button></form></details>
